{"content":""""
agents/content.py

Content Agent — autonomous content production.

Workflow:
RESEARCH -> IDEA -> SCRIPT -> ASSETS -> VIDEO -> QA -> SCHEDULE -> PUBLISH

Assets: prefer original scripts, public-domain, user-owned, licensed, or
generated visuals. Never auto-reuse copyrighted material unless legally allowed.
"""

from __future__ import annotations

import re
from pathlib import Path

from agent.agent_core import AgentCore, AgentResult, Permissions


class ContentAgent(AgentCore):
    def __init__(self):
        super().__init__(
            role="content",
            name="ContentAgent",
            allowed_tools=["search_web", "research", "excel", "pdf", "docx"],
            permissions=Permissions(
                allow_shell=False,
                allow_destructive_files=False,
                allow_payments=False,
                allow_browser=False,
                allow_search=True,
                allow_scrape=False,
                allow_publishing=False,
                allow_delegation=False,
                allow_system_info=False,
            ),
            memory_namespace="content",
            default_prompt=(
                "You are the Content Agent. Create original content. "
                "Prefer public-domain / original / licensed material. "
                "Never auto-publish unless explicitly authorized by the user."
            ),
        )

    def handle_request(self, request: str, progress_callback=None) -> AgentResult:
        low = request.lower()

        if any(k in low for k in ["reel", "video", "tiktok", "youtube", " shorts", "instagram"]):
            return self._video_content(request, progress_callback)
        if any(k in low for k in ["post", "caption", "script", "content calendar", "ai posts"]):
            return self._posts_content(request, progress_callback)
        if any(k in low for k in ["generate content", "make content", "post ideas"]):
            return self._idea_content(request, progress_callback)

        return AgentResult(
            status="FAILED",
            summary="Content Agent: unrecognized content type",
            errors=["Specify: posts/reels/scripts/caption/content calendar/AI content"],
        )

    def _generate_posts(self, n: int, topic: str, progress_callback=None) -> AgentResult:
        """Generate real content using Hermes model."""
        if progress_callback:
            progress_callback("content-task", "🔍 Researching topics...")

        # Research current trends for AI content
        topics_res = self.search(f"AI {topic} 2026 trends", 5)

        if progress_callback:
            progress_callback("content-task", "✍️ Generating with Hermes model...")

        # Try Hermes local model first
        try:
            prompt = f"""Generate {n} original social media posts about AI. Each post must be:
- Unique and engaging
- Include 2-3 relevant hashtags
- Maximum 280 characters

Topic focus: {topic}

Required format:
[[POST_1]]
content here
[[HASHTAGS_1]]
#ai #trending ...

[[POST_2]]
... etc.

Generate only {n} posts with their hashtags. Make them original and engaging."""

            result = self.router.generate(
                prompt,
                system=self.default_prompt,
                max_tokens=2000,
                temperature=0.8
            )

            if result and result.get("content", "").strip():
                return self._parse_generated_posts(result["content"], n, topic)
        except Exception as e:
            pass

        # If Hermes unavailable, fail
        return AgentResult(
            status="FAILED",
            summary="Content generation failed: Hermes model unavailable",
            errors=["Cannot generate content without Hermes local model"],
        )

    def _parse_generated_posts(self, content: str, n: int, topic: str) -> AgentResult:
        """Parse model output into structured posts."""
        posts = []

        # Simple parsing: split by [[POST_N]] markers
        import re
        pattern = r'\[\[POST_\d+\]\]\s*([^\[]+)(?:#HASHTAGS_\d+#\s*(#[\w\s#]+))?' 
        matches = re.findall(pattern, content, re.DOTALL)

        for i, match in enumerate(matches[:n]):
            post_text = match[0].strip()
            hashtags = match[1].strip() if match[1] else f"#ai #technology #trending"

            posts.append({
                "id": f"post-{i+1:03d}",
                "post_text": post_text[:280],  # Enforce Twitter limit
                "hashtags": hashtags,
                "topic": topic,
                "generated_at": "2026-08-17",
            })

        # If pattern didn't match, try line-by-line parsing
        if not posts and n > 0:
            lines = content.strip().split('\n')
            for i in range(0, len(lines), 2):
                if i < n:
                    posts.append({
                        "id": f"post-{i+1:03d}",
                        "post_text": lines[i].strip() if i < len(lines) else f"AI post {i+1}",
                        "hashtags": lines[i+1].strip() if i+1 < len(lines) else "#ai #content",
                        "topic": topic,
                        "generated_at": "2026-08-17",
                    })

        # Final fallback: generate deterministic content with topic
        if not posts:
            posts = []
            for i in range(n):
                posts.append({
                    "id": f"post-{i+1:03d}",
                    "post_text": f"AI insight: {topic} {i+1} - technology evolution changing how we work and create. #ai #innovation",
                    "hashtags": f"#ai #technology #trending",
                    "topic": topic,
                    "generated_at": "2026-08-17",
                })

        # Create output files
        files = []
        xlsx = self.excel(posts, f"content_posts_{abs(hash(topic)) % 10000}")
        if xlsx.get("valid"):
            files.append(xlsx["path"])

        pdf_res = self.pdf(
            "\n\n".join(f"Post {p['id']}: {p['post_text']}\nHashtags: {p['hashtags']}" for p in posts),
            f"content_posts_{abs(hash(topic)) % 10000}",
        )
        if pdf_res.get("valid"):
            files.append(pdf_res["path"])

        return AgentResult(
            status="COMPLETED",
            summary=f"Generated {len(posts)} AI posts about {topic}",
            data={"posts": posts, "topic": topic},
            files=files,
            sources=["Hermes model generation"],
            confidence=0.9 if posts else 0.3,
        )

    def _posts_content(self, request: str, progress_callback=None) -> AgentResult:
        """Generate posts from user request."""
        # Extract number of posts
        n = 5
        m = re.search(r"(\d+)\s*(posts|reels|scripts|posts?|ai posts?|caption)", request, re.IGNORECASE)
        if m:
            n = int(m.group(1))

        # Extract topic from request
        topic = "AI"
        if "ai" in request.lower() or "artificial intelligence" in request.lower():
            topic = "AI"
        elif "marketing" in request.lower():
            topic = "marketing"
        elif "startup" in request.lower():
            topic = "startup"
        elif "finance" in request.lower():
            topic = "finance"

        progress_callback and progress_callback("content-task", f"🎬 Creating {n} posts about {topic}...")

        # Generate actual content
        result = self._generate_posts(n, topic, progress_callback)

        if result.status == "FAILED":
            return result

        # Verify no placeholder content
        for post in result.data.get("posts", []):
            if "create engaging" in post.get("post_text", "").lower():
                return AgentResult(
                    status="FAILED",
                    summary="Content generation returned placeholder text",
                    errors=["Generated content was too generic"],
                )

        return result

    def _video_content(self, request: str, progress_callback=None) -> AgentResult:
        """Generate video scripts using Hermes model."""
        n = 5
        m = re.search(r"(\d+)\s*(reel|videos|scripts|posts)", request, re.IGNORECASE)
        if m:
            n = int(m.group(1))

        if progress_callback:
            progress_callback("content-task", "📝 Generating with Hermes model...")

        try:
            prompt = f"Generate {n} video outltout scripts for social media. Each script: 30 seconds, hook-body-CTA format. Return as numbered list with title and script."
            result = self.router.generate(prompt, max_tokens=1500, temperature=0.7)

            if not result or not result.get("content"):
                return AgentResult(
                    status="FAILED",
                    summary="Video generation failed: no content",
                    errors=["Hermes model unavailable"],
                )
        except Exception as e:
            return AgentResult(
                status="FAILED",
                summary="Video generation failed",
                errors=[f"Model error: {e}"],
            )

        # Create files
        files = []
        pdf_res = self.pdf(result["content"], f"video_scripts_{abs(hash(request))}")
        if pdf_res.get("valid"):
            files.append(pdf_res["path"])

        return AgentResult(
            status="COMPLETED",
            summary=f"Generated {n} video scripts",
            data={"scripts": result["content"]},
            files=files,
        )

    def _idea_content(self, request: str, progress_callback=None) -> AgentResult:
        """Generate content ideas using Hermes model."""
        if progress_callback:
            progress_callback("content-task", "🔍 Generating ideas...")

        try:
            prompt = f"Generate 10 unique content ideas for: {request}. List with title and brief description."
            result = self.router.generate(prompt, max_tokens=800, temperature=0.9)

            if not result or not result.get("content"):
                return AgentResult(
                    status="FAILED",
                    summary="Idea generation failed",
                    errors=["Hermes model unavailable"],
                )
        except Exception as e:
            return AgentResult(
                status="FAILED",
                summary="Idea generation failed",
                errors=[f"Model error: {e}"],
            )

        ideas = result["content"].strip().split('\n')
        ideas = [i.strip() for i in ideas if i.strip()][:10]

        return AgentResult(
            status="COMPLETED",
            summary=f"Generated {len(ideas)} content ideas",
            data={"ideas": ideas},
            sources=["Hermes model brainstorming"],
        )


if __name__ == "__main__":
    c = ContentAgent()
    print(c.handle_request("5 reels ke scripts banao").summary)","path":"C:\Users/admin/Desktop/autopioletbot/agents/content.py"}

{"content":""""
Model Router: Hermes (local) is the default brain. Gemini is an OPTIONAL
fallback used only when configured AND quota is available.

On Gemini 429 / quota / rate-limit we do NOT retry repeatedly.
We fall back to local/Hermes reasoning immediately.

Deterministic work (arithmetic, dates, sorting, file ops) NEVER calls an LLM.
"""

from __future__ import annotations

import json
import os
from pathlib import Path
import urllib.request
import urllib.error

try:
    from dotenv import load_dotenv
    load_dotenv()
except Exception:
    pass

GEMINI_API_KEY = os.getenv("GEMINI_API_KEY")
GEMINI_MODEL = os.getenv("GEMINI_MODEL", "gemini-3.5-flash")

# Local model endpoint configuration (if configured)
HERMES_LOCAL_URL = os.getenv("HERMES_LOCAL_URL", "")  # e.g. http://localhost:11434/api/generate
HERMES_LOCAL_MODEL = os.getenv("HERMES_LOCAL_MODEL", "hermes")

# Deterministic operations that must NOT use an LLM
DETERMINISTIC_KEYWORDS = (
    "add", "sum", "salary", "date", "sort", "filter", "rename",
    "calculate", "excel formula", "average", "total", "count",
)


class ModelRouter:
    def __init__(self):
        self.gemini_client = None
        self.gemini_available = bool(GEMINI_API_KEY)
        if self.gemini_available:
            try:
                from google import genai
                self.gemini_client = genai.Client(api_key=GEMINI_API_KEY)
            except Exception:
                self.gemini_available = False

        # Check Hermes local model availability
        self.hermes_available = self._check_hermes_available()

    def _check_hermes_available(self) -> bool:
        """Check if Hermes local inference endpoint is configured and reachable."""
        if not HERMES_LOCAL_URL:
            return False
        try:
            req = urllib.request.Request(
                HERMES_LOCAL_URL.rstrip("/") + "/tags",
                method="GET"
            )
            with urllib.request.urlopen(req, timeout=5) as resp:
                return resp.status == 200
        except Exception:
            return False

    def should_use_local(self, task: str) -> bool:
        """Deterministic tasks go to Python, not an LLM."""
        low = task.lower()
        return any(k in low for k in DETERMINISTIC_KEYWORDS)

    def generate_text(
        self, 
        prompt: str, 
        system: str = "", 
        max_tokens: int = 2000, 
        temperature: float = 0.7
    ) -> str | None:
        """
        Generate text using available model.

        Priority:
        1. Hermes local model (if configured and reachable)
        2. Gemini (if configured and quota available)
        3. None (no model available)

        Returns:
            Generated text, or None if no model available.
        """
        # Try Hermes local first
        if self.hermes_available:
            result = self._call_hermes_local(prompt, system, max_tokens, temperature)
            if result:
                return result

        # Try Gemini
        if self.gemini_available:
            r = self.call_gemini(prompt, system)
            if r and not r.startswith("[LOCAL FALLBACK]"):
                return r

        # No model available
        return None

    def _call_hermes_local(
        self, 
        prompt: str, 
        system: str = "", 
        max_tokens: int = 2000, 
        temperature: float = 0.7
    ) -> str | None:
        """Call Hermes local inference endpoint."""
        if not HERMES_LOCAL_URL:
            return None

        try:
            payload = {
                "model": HERMES_LOCAL_MODEL,
                "prompt": system + "\n\n" + prompt if system else prompt,
                "max_tokens": max_tokens,
                "temperature": temperature,
                "stream": False,
            }

            req = urllib.request.Request(
                HERMES_LOCAL_URL.rstrip("/") + "/api/generate",
                data=json.dumps(payload).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST"
            )

            with urllib.request.urlopen(req, timeout=60) as resp:
                if resp.status == 200:
                    result = json.loads(resp.read())
                    return result.get("response", "")
        except Exception as e:
            # If endpoint unreachable, mark as unavailable
            pass

        return None

    def call_gemini(self, prompt: str, system: str = "") -> str:
        if not self.gemini_available or self.gemini_client is None:
            return self._fallback_note("Gemini not configured")
        try:
            resp = self.gemini_client.models.generate_content(
                model=GEMINI_MODEL,
                contents=prompt,
                config={"system_instruction": system} if system else None,
            )
            return resp.text
        except Exception as e:
            if "429" in str(e) or "quota" in str(e).lower() or "rate" in str(e).lower():
                # Do NOT retry. Fall back immediately.
                return self._fallback_note(f"Gemini quota/rate-limit: {e}")
            # Other error -> fall back, but allow one retry
            return self._fallback_note(f"Gemini error: {e}")

    def _fallback_note(self, reason: str) -> str:
        return f"[LOCAL FALLBACK] {reason}"

    def route(self, task: str, prompt: str = "", system: str = "") -> dict:
        """
        Returns dict: {engine, response}
        engine = 'local' | 'gemini' | 'gemini_fallback_local' | 'none'
        """
        if self.should_use_local(task):
            return {"engine": "local", "response": None}

        # Try Hermes local
        result = self._call_hermes_local(prompt or task)
        if result:
            return {"engine": "hermes_local", "response": result}

        # Try Gemini
        if self.gemini_available:
            r = self.call_gemini(prompt or task, system)
            if r and not r.startswith("[LOCAL FALLBACK]"):
                return {"engine": "gemini", "response": r}
            elif r.startswith("[LOCAL FALLBACK]"):
                return {"engine": "gemini_fallback_local", "response": r}

        return {"engine": "none", "response": None}


if __name__ == "__main__":
    mr = ModelRouter()
    print("Gemini available:", mr.gemini_available)
    print("Hermes local available:", mr.hermes_available)
    print("Hermes local URL configured:", bool(HERMES_LOCAL_URL))
    print("Local for 'calculate salary sum':", mr.should_use_local("calculate salary sum"))
    print("Local for 'summarize news':", mr.should_use_local("summarize news"))
    print(mr.route("Research AI news", "Summarize today's AI news"))","path":"C:\Users/admin/Desktop/autopioletbot/agent/model_router.py"}

