    def _generate_posts(self, n: int, topic: str, progress_callback=None) -> AgentResult:
        """Generate real content using model or fail if no model available."""
        if progress_callback:
            progress_callback("content-task", f"🔍 Researching {topic}...")

        # Research to inform topic
        try:
            topics_res = self.search(f"{topic} 2026 trends", 3)
        except Exception:
            topics_res = ""

        if progress_callback:
            progress_callback("content-task", "✍️ Generating content with model...")

        # Build prompt for content generation
        prompt = f"""Generate {n} unique social media posts about {topic}. Format exactly:

Post 1:
[text]
[hashtags]

Post 2:
[text]
[hashtags]

Post {n}:
[text]
[hashtags]

Each post must be:
- Original and engaging
- Under 280 characters for the text
- Include 2-5 relevant hashtags
- Topic-focused on {topic}

No explanations needed, just the posts."""

        # Try to generate with model
        generated = self.router.generate_text(
            prompt,
            system=self.default_prompt,
            max_tokens=1500,
            temperature=0.7
        )

        # If no model available, fail
        if generated is None:
            return AgentResult(
                status="FAILED",
