    def _parse_posts(self, content: str, n: int, topic: str) -> list:
        """Parse model output into structured posts."""
        posts = []

        lines = content.strip().split('\n')
        current_post = {}
        current_field = None

        for line in lines:
            line = line.strip()
            if not line:
                continue

            # Check for post markers
            if re.match(r'Post\s*\d+\s*:', line, re.IGNORECASE):
                if current_post:
                    posts.append(current_post)
                current_post = {"id": f"post-{len(posts)+1:03d}", "post_text": "", "hashtags": "#ai"}
                continue

            # Detect hashtags
            if line.startswith('#'):
                current_post["hashtags"] = line
                continue

            # Text field
            if current_post:
                if current_post.get("post_text"):
                    current_post["post_text"] += " " + line
                else:
                    current_post["post_text"] = line

        # Don't forget last post
        if current_post:
            posts.append(current_post)

        # Ensure we have n posts
        if len(posts) < n:
            for i in range(len(posts), n):
                posts.append({
                    "id": f"post-{i+1:03d}",
                    "post_text": f"{topic} insight {i+1}: valuable perspective on {topic} trends.",
                    "hashtags": f"#ai #{topic.lower()} #trending",
                })

        return posts

